{
  "name": "secure-stealth-chat",
  "version": "1.0.0",
  "description": "Zero-knowledge end-to-end encrypted ephemeral communication app",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "ws": "^8.18.0"
  }
}

const http = require('http');
const fs = require('fs');
const path = require('path');
const os = require('os');
const { WebSocketServer } = require('ws');

const PORT = process.env.PORT || 3000;
const PUBLIC_DIR = path.join(__dirname, 'public');

// MIME types for static assets
const MIME_TYPES = {
  '.html': 'text/html; charset=UTF-8',
  '.css': 'text/css; charset=UTF-8',
  '.js': 'application/javascript; charset=UTF-8',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon'
};

// Helper: Get local network IP addresses
function getLocalIpAddresses() {
  const interfaces = os.networkInterfaces();
  const addresses = [];
  for (const name of Object.keys(interfaces)) {
    for (const net of interfaces[name]) {
      // Skip internal (127.0.0.1) and non-IPv4
      if (net.family === 'IPv4' && !net.internal) {
        addresses.push({ interface: name, address: net.address });
      }
    }
  }
  return addresses;
}

// HTTP Server: Serves frontend & network diagnostics
const server = http.createServer((req, res) => {
  // CORS & Security headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');

  // Network info API for easy phone hotspot connection
  if (req.url === '/api/network-info') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({
      port: PORT,
      ips: getLocalIpAddresses(),
      serverTime: Date.now()
    }));
  }

  // Parse path and serve static files
  let safePath = path.normalize(req.url.split('?')[0]);
  if (safePath === '/' || safePath === '\\') safePath = '/index.html';
  const filePath = path.join(PUBLIC_DIR, safePath);

  // Security check: keep inside PUBLIC_DIR
  if (!filePath.startsWith(PUBLIC_DIR)) {
    res.writeHead(403);
    return res.end('Access Denied');
  }

  fs.stat(filePath, (err, stats) => {
    if (err || !stats.isFile()) {
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      return res.end('404 Not Found');
    }

    const ext = path.extname(filePath).toLowerCase();
    const contentType = MIME_TYPES[ext] || 'application/octet-stream';
    res.writeHead(200, { 'Content-Type': contentType });
    fs.createReadStream(filePath).pipe(res);
  });
});

// Ephemeral In-Memory Room Hub (Zero Disk Persistence)
// Map<roomId, Set<WebSocket>>
const rooms = new Map();

const wss = new WebSocketServer({ server });

wss.on('connection', (ws) => {
  let currentRoom = null;
  let peerId = null;

  ws.on('message', (raw) => {
    try {
      const data = JSON.parse(raw);

      switch (data.type) {
        case 'join': {
          currentRoom = data.roomId;
          peerId = data.peerId || 'anon-' + Math.random().toString(36).substring(2, 7);

          if (!rooms.has(currentRoom)) {
            rooms.set(currentRoom, new Set());
          }
          rooms.get(currentRoom).add(ws);

          // Broadcast peer count to room
          const count = rooms.get(currentRoom).size;
          broadcastToRoom(currentRoom, {
            type: 'presence',
            event: 'join',
            peerId,
            peerCount: count
          });
          break;
        }

        case 'encrypted_message': {
          if (!currentRoom || !rooms.has(currentRoom)) return;
          // Relay ONLY the encrypted payload. Server never has keys to decrypt.
          broadcastToRoom(currentRoom, {
            type: 'encrypted_message',
            payload: data.payload,
            timestamp: Date.now()
          }, ws); // Skip sender
          break;
        }

        case 'typing': {
          if (!currentRoom) return;
          broadcastToRoom(currentRoom, {
            type: 'typing',
            sender: data.sender
          }, ws);
          break;
        }

        case 'leave': {
          cleanup();
          break;
        }
      }
    } catch (e) {
      // Invalid JSON or format, drop silently
    }
  });

  const cleanup = () => {
    if (currentRoom && rooms.has(currentRoom)) {
      const set = rooms.get(currentRoom);
      set.delete(ws);
      if (set.size === 0) {
        // Completely destroy room from RAM when everyone leaves
        rooms.delete(currentRoom);
      } else {
        broadcastToRoom(currentRoom, {
          type: 'presence',
          event: 'leave',
          peerId,
          peerCount: set.size
        });
      }
      currentRoom = null;
    }
  };

  ws.on('close', cleanup);
  ws.on('error', cleanup);
});

function broadcastToRoom(roomId, messageObj, excludeWs = null) {
  const room = rooms.get(roomId);
  if (!room) return;
  const serialized = JSON.stringify(messageObj);
  for (const client of room) {
    if (client !== excludeWs && client.readyState === client.OPEN) {
      client.send(serialized);
    }
  }
}

