/**
 * ZERO-KNOWLEDGE CLIENT-SIDE CRYPTOGRAPHIC ENGINE
 * Implements military-grade AES-256-GCM + PBKDF2 using native Web Crypto API.
 * All encryption and decryption occurs EXCLUSIVELY in client RAM.
 * Neither plaintexts nor secret keys ever touch the network or disk.
 */

class StealthCrypto {
  constructor() {
    this.activeKey = null;
    this.roomSalt = null;
    this.rawPassphrase = null;
  }

  // ArrayBuffer <-> Base64 helpers
  static bufferToBase64(buf) {
    let binary = '';
    const bytes = new Uint8Array(buf);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return window.btoa(binary);
  }

  static base64ToBuffer(b64) {
    const binary = window.atob(b64);
    const len = binary.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes.buffer;
  }

  // Generate cryptographically secure random bytes
  static getRandomBytes(length) {
    const arr = new Uint8Array(length);
    window.crypto.getRandomValues(arr);
    return arr;
  }

  // Generate secure random room ID or passphrase
  static generateSecretKey(length = 24) {
    const charset = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789!@#$%^&*';
    const randomVals = new Uint8Array(length);
    window.crypto.getRandomValues(randomVals);
    let result = '';
    for (let i = 0; i < length; i++) {
      result += charset[randomVals[i] % charset.length];
    }
    return result;
  }

  /**
   * Derive AES-256-GCM key from user passphrase using PBKDF2 (100,000 rounds of SHA-256)
   */
  async initializeKey(passphrase, saltBuffer = null) {
    this.rawPassphrase = passphrase;
    const enc = new TextEncoder();
    const keyMaterial = await window.crypto.subtle.importKey(
      'raw',
      enc.encode(passphrase),
      { name: 'PBKDF2' },
      false,
      ['deriveKey']
    );

    // If no salt provided, generate a fresh 16-byte salt
    if (!saltBuffer) {
      this.roomSalt = StealthCrypto.getRandomBytes(16);
    } else {
      this.roomSalt = new Uint8Array(saltBuffer);
    }

    // Derive 256-bit AES-GCM Key
    this.activeKey = await window.crypto.subtle.deriveKey(
      {
        name: 'PBKDF2',
        salt: this.roomSalt,
        iterations: 100000,
        hash: 'SHA-256'
      },
      keyMaterial,
      { name: 'AES-GCM', length: 256 },
      false, // non-extractable from RAM for maximum security
      ['encrypt', 'decrypt']
    );

    return StealthCrypto.bufferToBase64(this.roomSalt.buffer);
  }

  /**
   * Encrypt arbitrary string (text, JSON, file metadata)
   */
  async encrypt(plaintext) {
    if (!this.activeKey) {
      throw new Error('Cryptographic key not initialized');
    }

    const enc = new TextEncoder();
    const encoded = enc.encode(plaintext);

    // 12-byte IV standard for AES-GCM
    const iv = StealthCrypto.getRandomBytes(12);

    const encryptedBuffer = await window.crypto.subtle.encrypt(
      {
        name: 'AES-GCM',
        iv: iv
      },
      this.activeKey,
      encoded
    );

    return {
      ciphertext: StealthCrypto.bufferToBase64(encryptedBuffer),
      iv: StealthCrypto.bufferToBase64(iv.buffer),
      salt: StealthCrypto.bufferToBase64(this.roomSalt.buffer)
    };
  }

  /**
   * Decrypt payload using active key
   */
  async decrypt(encryptedObj) {
    if (!this.activeKey) {
      throw new Error('Cryptographic key not initialized');
    }

    try {
      const ciphertextBuf = StealthCrypto.base64ToBuffer(encryptedObj.ciphertext);
      const ivBuf = StealthCrypto.base64ToBuffer(encryptedObj.iv);

      const decryptedBuffer = await window.crypto.subtle.decrypt(
        {
          name: 'AES-GCM',
          iv: new Uint8Array(ivBuf)
        },
        this.activeKey,
        ciphertextBuf
      );

      const dec = new TextDecoder();
      return dec.decode(decryptedBuffer);
    } catch (err) {
      // AES-GCM authentication tag failed -> wrong key or manipulated ciphertext
      throw new Error('Decryption Failed: Authentication Tag mismatch or incorrect Secret Passphrase.');
    }
  }

  /**
   * Secure RAM Wipe: Nuke key references
   */
  destroy() {
    this.activeKey = null;
    this.roomSalt = null;
    this.rawPassphrase = null;
  }
}

// Global instance
window.stealthCrypto = new StealthCrypto();

