  async decrypt(payload) {
    if (!this.activeKey) {
      throw new Error('Cryptographic key not initialized');
    }

    const { ciphertext, iv, authTag } = payload;

    // 1. Verify HMAC
    const expectedTag = CryptoJS.HmacSHA256(ciphertext + iv, this.activeKey).toString();
