args.ReplacementContent:
@media (max-width: 768px) {
  .site-header { padding: 10px 16px; }
  .chat-controls-bar { flex-direction: column; gap: 8px; align-items: flex-start; }
  .msg-row { max-width: 90%; }
  .security-highlights { grid-template-columns: 1fr; }
  .lobby-card { padding: 24px 18px; }
}

/* ==========================================================================
   ANTI-KEYLOGGER VIRTUAL SCRAMBLED KEYPAD
   ========================================================================== */
.virtual-keypad-box {
  background: rgba(10, 14, 22, 0.95);
  border: 1px solid var(--border-color);
  border-radius: 14px;
  padding: 16px;
  margin-bottom: 20px;
  animation: fadeInMsg 0.2s ease-out;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
}

.keypad-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--accent-emerald);
  margin-bottom: 12px;
}

.keypad-mini-btn {
  background: rgba(16, 185, 129, 0.15);
  border: 1px solid rgba(16, 185, 129, 0.3);
  color: var(--accent-emerald);
  padding: 3px 8px;
  border-radius: 6px;
  font-size: 0.72rem;
  cursor: pointer;
  transition: var(--transition);
}

.keypad-mini-btn:hover {
  background: var(--accent-emerald);
  color: #000;
}

.keypad-grid {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 6px;
  margin-bottom: 10px;
}

.keypad-key-btn {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-color);
  color: #fff;
  border-radius: 6px;
  height: 34px;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
}

.keypad-key-btn:hover {
  background: rgba(16, 185, 129, 0.25);
  border-color: var(--accent-emerald);
  color: var(--accent-emerald);
  transform: translateY(-1px);
}

.keypad-key-btn:active {
  transform: scale(0.95);
  background: var(--accent-emerald);
  color: #000;
}

.keypad-actions {
  display: flex;
  gap: 8px;
}

.keypad-ctrl-btn {
  flex: 1;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  border-radius: 6px;
  padding: 8px;
  font-size: 0.78rem;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
}

.keypad-ctrl-btn:hover {
  background: rgba(255, 255, 255, 0.15);
  color: #fff;
}

@media (max-width: 480px) {
  .keypad-grid {
    grid-template-columns: repeat(6, 1fr);
  }
}

