// Anti-Keylogger Virtual Keypad (Bank-Grade Defense)
const btnToggleKeypad = document.getElementById('btnToggleKeypad');
const virtualKeypadDrawer = document.getElementById('virtualKeypadDrawer');
const keypadGrid = document.getElementById('keypadGrid');
const btnShuffleKeypad = document.getElementById('btnShuffleKeypad');
const btnKeypadSpace = document.getElementById('btnKeypadSpace');
const btnKeypadBackspace = document.getElementById('btnKeypadBackspace');
const btnKeypadClear = document.getElementById('btnKeypadClear');

let keypadChars = 'abcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*-_+=?'.split('');

const shuffleArray = (arr) => {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
};

const renderKeypad = () => {
  keypadGrid.innerHTML = '';
  shuffleArray(keypadChars);
  keypadChars.forEach(char => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'keypad-key-btn';
    btn.textContent = char;
    btn.addEventListener('click', () => {
      passphraseInput.value += char;
      playChirp(700, 'sine', 0.03);
    });
    keypadGrid.appendChild(btn);
  });
};

if (btnToggleKeypad) {
  btnToggleKeypad.addEventListener('click', () => {
    const isHidden = virtualKeypadDrawer.style.display === 'none';
    virtualKeypadDrawer.style.display = isHidden ? 'block' : 'none';
    if (isHidden) renderKeypad();
  });
}

if (btnShuffleKeypad) {
  btnShuffleKeypad.addEventListener('click', () => {
    renderKeypad();
    playChirp(900, 'triangle', 0.04);
  });
}

if (btnKeypadSpace) btnKeypadSpace.addEventListener('click', () => { passphraseInput.value += ' '; });
if (btnKeypadBackspace) btnKeypadBackspace.addEventListener('click', () => { passphraseInput.value = passphraseInput.value.slice(0, -1); });
if (btnKeypadClear) btnKeypadClear.addEventListener('click', () => { passphraseInput.value = ''; });

