  if (!saltHex) {
    const saltWords = CryptoJS.lib.WordArray.random(16);
    this.saltHex = saltWords.toString();
  } else {
    this.saltHex = saltHex;
  }

  const salt = CryptoJS.enc.Hex.parse(this.saltHex);

  this.activeKey = CryptoJS.PBKDF2(passphrase, salt, {
    keySize: 256 / 32,
    iterations: 10000,
    hasher: CryptoJS.algo.SHA256
  });

  return this.saltHex;
}

