/* Chat Subheader Controls */
.chat-controls-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 24px;
  background: rgba(13, 17, 26, 0.9);
  border-bottom: 1px solid var(--border-color);
  font-size: 0.85rem;
}

.room-meta-group {
  display: flex;
  align-items: center;
  gap: 16px;
}

.room-tag {
  font-family: var(--font-mono);
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-color);
  padding: 4px 10px;
  border-radius: 6px;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 6px;
}

.peer-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--accent-emerald);
  font-weight: 600;
}

.control-actions-group {
  display: flex;
  align-items: center;
  gap: 12px;
}

.burn-selector {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(0, 0, 0, 0.4);
  padding: 4px 10px;
  border-radius: 6px;
  border: 1px solid var(--border-color);
  font-size: 0.8rem;
  color: var(--text-muted);
}

.burn-selector select {
  background: transparent;
  color: var(--accent-amber);
  border: none;
  font-family: var(--font-mono);
  font-weight: 600;
  cursor: pointer;
}

.burn-selector select:focus {
  outline: none;
}

.tool-toggle-btn {
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  padding: 5px 10px;
  border-radius: 6px;
  font-size: 0.78rem;
  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  gap: 5px;
}

.tool-toggle-btn:hover, .tool-toggle-btn.active {
  background: rgba(16, 185, 129, 0.15);
  border-color: var(--accent-emerald);
  color: var(--accent-emerald);
}

