const server = http.createServer((req, res) => {
  // CORS & Security headers
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('Content-Security-Policy', "default-src 'self'; img-src 'self' data:; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; connect-src 'self' ws: wss:; object-src 'none'; base-uri 'none'; form-action 'none';");

  // Network info API for easy phone hotspot connection
  if (req.url === '/api/network-info') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({
      port: PORT,
      ips: getLocalIpAddresses(),
      serverTime: Date.now()
    }));
  }

  // Favicon handler
  if (req.url === '/favicon.ico') {
    res.writeHead(204);
    return res.end();
  }

  // Serve static files
  let safePath = path.normalize(req.url.split('?')[0]);
  if (safePath === '/' || safePath === '\\') {
    safePath = '/index.html';
  }

  const filePath = path.join(PUBLIC_DIR, safePath);

  // Prevent directory traversal
  if (!filePath.startsWith(PUBLIC_DIR)) {
    res.writeHead(403, { 'Content-Type': 'text/plain' });
    return res.end('Access Denied');
  }

  const ext = path.extname(filePath);
  const contentType = MIME_TYPES[ext] || 'application/octet-stream';

  fs.readFile(filePath, (err, content) => {
    if (err) {
      if (err.code === 'ENOENT') {
        res.writeHead(404, { 'Content-Type': 'text/plain' });
        res.end('404 Not Found');
      } else {
        res.writeHead(500, { 'Content-Type': 'text/plain' });
        res.end('500 Server Error');
      }
    } else {
      res.writeHead(200, { 'Content-Type': contentType });
      res.end(content);
    }
  });
});

// Ephemeral In-Memory Room Hub (Zero Disk Persistence)
// Map<roomId, Set<WebSocket>>
const rooms = new Map();

// Anti-DoS Tracking
const ipConnections = new Map(); // ip -> count
const MAX_CONNS_PER_IP = 15;

const wss = new WebSocketServer({ 
  server,
  maxPayload: 5 * 1024 * 1024 // 5MB max packet limit (supports encrypted Base64 photos + text)
});

wss.on('connection', (ws, req) => {
  const forwarded = req.headers['x-forwarded-for'];
  const clientIp = (forwarded ? forwarded.split(',')[0].trim() : req.socket.remoteAddress) || 'unknown';

  // 1. IP Rate Limiting (Anti-DoS connection flooding)
  const currentConns = ipConnections.get(clientIp) || 0;
  if (currentConns >= MAX_CONNS_PER_IP) {
    ws.close(1008, 'Anti-DoS: Connection limit exceeded');
    return;
  }
  ipConnections.set(clientIp, currentConns + 1);

  let currentRoom = null;
  let peerId = null;
  let messageCountInWindow = 0;
  let lastWindowReset = Date.now();

  ws.on('message', (raw) => {
    try {
      // 2. Message Rate Throttling (Anti-Spam / Anti-Flood: Max 20 msgs / sec)
      const now = Date.now();
      if (now - lastWindowReset > 1000) {
        messageCountInWindow = 0;
        lastWindowReset = now;
      }
      messageCountInWindow++;
      if (messageCountInWindow > 20) {
        // Drop flooded packet silently to prevent CPU spike
        return;
      }

      const data = JSON.parse(raw);

      switch (data.type) {
        case 'join': {
          currentRoom = data.roomId;
          peerId = data.peerId || 'anon-' + Math.random().toString(36).substring(2, 7);

          if (!rooms.has(currentRoom)) {
            rooms.set(currentRoom, new Set());
          }
          rooms.get(currentRoom).add(ws);

          // Broadcast peer count to room
          const count = rooms.get(currentRoom).size;
          broadcastToRoom(currentRoom, {
            type: 'presence',
            event: 'join',
            peerId,
            peerCount: count
          });
          break;
        }

        case 'encrypted_message': {
          if (!currentRoom || !rooms.has(currentRoom)) return;
          // Relay ONLY the encrypted payload. Server never has keys to decrypt.
          broadcastToRoom(currentRoom, {
            type: 'encrypted_message',
            payload: data.payload,
            timestamp: Date.now()
          }, ws); // Skip sender
          break;
        }

        case 'typing': {
          if (!currentRoom) return;
          broadcastToRoom(currentRoom, {
            type: 'typing',
            sender: data.sender
          }, ws);
          break;
        }

        case 'wipe_room': {
          const targetRoom = data.roomId || currentRoom;
          if (targetRoom && rooms.has(targetRoom)) {
            const peerSet = rooms.get(targetRoom);
            for (const client of peerSet) {
              try {
                if (client.readyState === 1) { // WebSocket.OPEN
                  client.send(JSON.stringify({ type: 'room_wiped', roomId: targetRoom }));
                  client.close(1000, 'Room wiped');
                }
              } catch (e) {}
            }
            rooms.delete(targetRoom);
          }
          cleanup();
          break;
        }

        case 'leave': {
          cleanup();
          break;
        }
      }
    } catch (e) {
      // Invalid JSON or format, drop silently
    }
  });

