.send-msg-btn:hover {
  transform: scale(1.05);
  background: #34d399;
}

/* Photo Attachment Button */
.chat-attach-btn {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid var(--border-color);
  color: var(--text-muted);
  width: 44px;
  height: 44px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: var(--transition);
  flex-shrink: 0;
}

.chat-attach-btn:hover {
  background: rgba(6, 182, 212, 0.15);
  border-color: var(--accent-cyan);
  color: var(--accent-cyan);
  transform: scale(1.05);
}

/* In-Memory Pending Image Preview Pill */
.image-preview-container {
  padding: 10px 24px 0 24px;
  background: var(--bg-card);
  backdrop-filter: blur(16px);
}

.image-preview-card {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: rgba(13, 17, 26, 0.95);
  border: 1px solid rgba(6, 182, 212, 0.4);
  border-radius: 12px;
  padding: 6px 12px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.4);
  animation: popoverFadeIn 0.2s ease-out;
}

.preview-thumbnail {
  width: 40px;
  height: 40px;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.preview-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.preview-name {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-main);
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.preview-size {
  font-size: 0.7rem;
  font-family: var(--font-mono);
  color: var(--accent-cyan);
}

.preview-cancel-btn {
  background: transparent;
  border: none;
  color: var(--accent-crimson);
  font-size: 1rem;
  cursor: pointer;
  padding: 4px;
  border-radius: 4px;
  transition: var(--transition);
}

.preview-cancel-btn:hover {
  background: rgba(239, 68, 68, 0.2);
}

/* Rendered Message Images */
.msg-image-wrap {
  margin-top: 8px;
  border-radius: 10px;
  overflow: hidden;
  max-width: 320px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  cursor: pointer;
  position: relative;
}

.chat-image-preview {
  display: block;
  width: 100%;
  max-height: 260px;
  object-fit: cover;
  border-radius: 8px;
  transition: transform 0.2s ease, filter 0.2s ease;
}

.chat-image-preview:hover {
  transform: scale(1.02);
  filter: brightness(1.08);
}

/* Zero-Knowledge Image Lightbox Modal */
.image-lightbox-modal {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  z-index: 5000;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: popoverFadeIn 0.2s ease-out;
}

.lightbox-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.88);
  backdrop-filter: blur(16px);
}

.lightbox-dialog {
  position: relative;
  z-index: 5001;
  max-width: 90vw;
  max-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

.lightbox-dialog img {
  max-width: 90vw;
  max-height: 85vh;
  object-fit: contain;
  border-radius: 12px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.9), 0 0 30px rgba(16, 185, 129, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.15);
}

.lightbox-close-btn {
  position: absolute;
  top: -40px;
  right: 0;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #fff;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  cursor: pointer;
  transition: var(--transition);
}

.lightbox-close-btn:hover {
  background: #ef4444;
  border-color: #ef4444;
}

/* WIPE Button Special Glow */
.wipe-btn {
  background: linear-gradient(135deg, rgba(239, 68, 68, 0.35), rgba(185, 28, 28, 0.5));
  border: 1px solid #ef4444;
  color: #fee2e2;
  font-weight: 800;
  letter-spacing: 0.08em;
  box-shadow: 0 0 15px rgba(239, 68, 68, 0.3);
}

.wipe-btn:hover {
  background: linear-gradient(135deg, #ef4444, #b91c1c);
  color: #fff;
  box-shadow: 0 0 25px rgba(239, 68, 68, 0.6);
}

